/* Equation (linear, with symbol palette) */
function wEquation() { const sy = '± × ÷ ≠ ≤ ≥ ≈ ∞ √ ∛ ∑ ∏ ∫ ∂ ∆ ∇ π θ α β γ λ μ σ φ ω ° ′ ″ ← → ⇒ ⇔ ∈ ∉ ⊂ ∪ ∩ ∀ ∃ ½ ² ³ ⁿ ₁ ₂ ₙ'.split(' ');
  wDlg('Equation', `<div style="display:flex;flex-wrap:wrap;gap:3px;margin-bottom:6px">${sy.map(s => `<button class="weqs" style="min-width:30px;height:30px;border:1px solid #ccc;background:#fff">${s}</button>`).join('')}</div><label>Equation (use ^ for superscript, _ for subscript, a/b for fractions)</label><input type="text" id="eqT" value="x = (−b ± √(b^2 − 4ac)) / 2a"><div id="eqP" class="weq" style="display:block;margin-top:8px;padding:8px;font-size:18px"></div><label>Common</label><select id="eqC"><option value="">—</option><option>A = πr^2</option><option>a^2 + b^2 = c^2</option><option>(x + a)^n = ∑_(k=0)^n (n k) x^k a^(n−k)</option><option>e^(iπ) + 1 = 0</option><option>f(x) = a_0 + ∑_(n=1)^∞ (a_n cos(nπx/L))</option></select>`, [['Insert', () => { const h = wEqHtml(wv('eqT')); closeG(); wHTML(`<span class="weq" contenteditable="false" data-eq="${wesc(wv('eqT') || '')}">${h}</span>&nbsp;`); }]]);
  const pv = () => $('eqP').innerHTML = wEqHtml(wv('eqT')); $('eqT').oninput = pv; $('eqC').onchange = () => { if (wv('eqC')) { $('eqT').value = wv('eqC'); pv(); } }; document.querySelectorAll('.weqs').forEach(b => b.onclick = () => { const i = $('eqT'); const p = i.selectionStart; i.value = i.value.slice(0, p) + b.textContent + i.value.slice(i.selectionEnd); i.focus(); i.selectionStart = i.selectionEnd = p + b.textContent.length; pv(); }); pv(); }
function wEqHtml(t) { let h = wesc(t || ''); const grp = '(\\([^()]*\\)|[\\wπθαβγλμσφω∞]+)'; h = h.replace(new RegExp('\\^' + grp, 'g'), (m, g) => `<sup>${g.replace(/^\(|\)$/g, '')}</sup>`).replace(new RegExp('_' + grp, 'g'), (m, g) => `<sub>${g.replace(/^\(|\)$/g, '')}</sub>`); return h; }
