const WCOVERS = [['Banded', '#2f5496', '#fff'], ['Facet', '#70ad47', '#fff'], ['Ion', '#c55a11', '#fff'], ['Retrospect', '#404040', '#fff'], ['Simple', '#ffffff', '#2f5496']];
