function wCover(i) { const c = WCOVERS[i]; wSnap(); const old = WB().querySelector('.wcover'); if (old) { const nx = old.nextElementSibling; if (nx && nx.classList.contains('pb')) nx.remove(); old.remove(); } const d = new Date().toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' }); const html = `<div class="wcover" style="background:${c[1]};color:${c[2]};padding:120px 40px;margin:-24px calc(-1 * var(--mx,96px)) 0;min-height:700px;box-sizing:border-box"><p style="font-size:12pt;letter-spacing:2px;text-transform:uppercase;margin:0">[Company name]</p><p style="font-size:40pt;font-family:'Calibri Light';margin:40px 0 10px;line-height:1.1">[Document title]</p><p style="font-size:16pt;margin:0 0 60px">[Document subtitle]</p><p style="font-size:11pt;margin:0">${wesc(WD.author)}<br>${d}</p></div><div class="pb" contenteditable="false">— page break —</div>`; WB().insertAdjacentHTML('afterbegin', html); wAfter(); WB().scrollTop = 0; $('desk').scrollTop = 0; }
