function wPageSetupDlg() { const m = WD.marg || [1, 1, 1, 1]; wDlg('Page Setup', `<b style="font-size:12px">Margins (inches)</b><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:6px"><div><label>Top</label><input type="number" step="0.1" id="psT" value="${m[0]}"></div><div><label>Left</label><input type="number" step="0.1" id="psL" value="${m[1]}"></div><div><label>Bottom</label><input type="number" step="0.1" id="psB" value="${m[2]}"></div><div><label>Right</label><input type="number" step="0.1" id="psR" value="${m[3]}"></div></div><label>Orientation</label><select id="psO"><option value="0">Portrait</option><option value="1" ${pgS.land ? 'selected' : ''}>Landscape</option></select><label>Paper size</label><select id="psZ">${Object.entries(WSIZES).map(([k, v]) => `<option value="${k}" ${pgS.sz === k ? 'selected' : ''}>${v[0]} (${v[1]})</option>`).join('')}</select><label>Vertical alignment</label><select id="psV"><option value="">Top</option><option value="center">Center</option></select><label><input type="checkbox" id="psDF" ${WD.diffFirst ? 'checked' : ''}> Different first page header/footer</label>`, [['OK', () => { WD.diffFirst = wv('psDF'); setPage({ land: wv('psO') === '1', sz: wv('psZ') }); wSetMargins([+wv('psT'), +wv('psL'), +wv('psB'), +wv('psR')]); closeG(); }]]); }
function wColumns(n, kind) { wSnap(); const r = wSel(); const sel = r && !r.collapsed; if (!sel) { WD.cols = n; WD.colKind = kind; save(); wColsPaint(); wAfter(); return; } const bs = blocksInSel(); if (!bs.length) return; const wrap = document.createElement('div'); wrap.className = 'wcols'; wrap.style.columnCount = n; if (kind) wrap.dataset.k = kind; bs[0].before(wrap); bs.forEach(b => wrap.appendChild(b)); wAfter(); }
