/* ======================= REFERENCES ======================= */
function wTocMenu(btn) { wMenu(btn, [{ t: '<b>Automatic Table 1</b><br><small>Heading levels 1–3 with page numbers</small>', f: () => wToc(3, true) }, { t: '<b>Automatic Table 2</b><br><small>Levels 1–2</small>', f: () => wToc(2, true) }, { t: '<b>Manual Table</b><br><small>No page numbers</small>', f: () => wToc(3, false) }, '-', { t: 'Update Table', f: wTocUpdate }, { t: 'Remove Table of Contents', f: () => { const t = WB().querySelector('.toc'); if (t) { wSnap(); t.remove(); wAfter(); } } }]); }
function wTocHtml(lv, pages) { const sel = ['h1', 'h2', 'h3', 'h4'].slice(0, lv).join(',') + ',[data-lvl]'; const hs = [...WB().querySelectorAll(sel)].filter(h => !h.closest('.toc')); const pageH = pg.h / 15; return `<div class="toc" contenteditable="false" data-lv="${lv}" data-pg="${pages ? 1 : 0}"><p style="font-size:16pt;color:#2f5496;margin-bottom:6pt">Contents</p>` + (hs.length ? hs.map((h, i) => { if (!h.id) h.id = 'toc' + Date.now().toString(36) + i; const l = +(h.dataset.lvl || h.nodeName[1] || 1); const pgn = Math.max(1, Math.floor((h.offsetTop) / pageH) + 1); return `<p style="margin:2px 0 2px ${(l - 1) * 18}px;display:flex"><a href="#${h.id}" style="color:inherit;text-decoration:none;flex:0 1 auto">${wesc(h.textContent)}</a>${pages ? `<span style="flex:1;border-bottom:1px dotted #777;margin:0 4px 4px"></span><span>${pgn}</span>` : ''}</p>`; }).join('') : '<p><i>No table of contents entries found.</i></p>') + '</div>'; }
function wToc(lv, pages) { wSnap(); const old = WB().querySelector('.toc'); if (old) { old.outerHTML = wTocHtml(lv, pages); wAfter(); return; } wInsBlock(wTocHtml(lv, pages)); }
function wTocUpdate() { const t = WB().querySelector('.toc'); if (!t) { alert('There is no table of contents. Use References > Table of Contents.'); return; } wSnap(); t.outerHTML = wTocHtml(+t.dataset.lv || 3, t.dataset.pg !== '0'); wAfter(); stMsgW('Table of contents updated'); }
insTOC = () => wToc(3, true);
WB().addEventListener('click', e => { const a = e.target.closest('.toc a, a.xref'); if (a) { e.preventDefault(); const t = document.getElementById(a.getAttribute('href').slice(1)); t && t.scrollIntoView({ block: 'start', behavior: 'smooth' }); } });
function wAddText(btn) { wMenu(btn, [{ t: 'Do Not Show in Table of Contents', f: () => wStyle('p') }, { t: 'Level 1', f: () => wStyle('h1') }, { t: 'Level 2', f: () => wStyle('h2') }, { t: 'Level 3', f: () => wStyle('h3') }]); }
/* Footnotes & endnotes (real numbering, notes area) */
function wNote(kind) { const r = wSel(); if (!r) return; const lr = r.cloneRange(); lr.collapse(false); RB.ask(kind === 'fn' ? 'Footnote text' : 'Endnote text', '', t => { if (t === null) return; lastSel = lr; restore(); const id = kind + Date.now().toString(36); wHTML(`<span class="${kind}ref" contenteditable="false" data-id="${id}">0</span>`); let box = WB().querySelector(`.notes[data-k="${kind}"]`); if (!box) { box = document.createElement('div'); box.className = 'notes'; box.dataset.k = kind; box.contentEditable = 'false'; if (kind === 'en') box.style.width = '100%'; WB().appendChild(box); } const p = document.createElement('p'); p.contentEditable = 'true'; p.dataset.id = id; p.innerHTML = `<span class="nnum">0</span> ${wesc(t)}`; box.appendChild(p); wRenum(); wAfter(); }); }
function wRenum() { for (const k of ['fn', 'en']) { const refs = [...WB().querySelectorAll('.' + k + 'ref')]; const box = WB().querySelector(`.notes[data-k="${k}"]`); refs.forEach((r, i) => { const lab = k === 'fn' ? String(i + 1) : ['i', 'ii', 'iii', 'iv', 'v', 'vi', 'vii', 'viii', 'ix', 'x'][i] || String(i + 1); r.textContent = lab; if (box) { const p = box.querySelector(`p[data-id="${r.dataset.id}"]`); if (p) { p.querySelector('.nnum').textContent = lab; box.appendChild(p); } } }); if (box && !(box.previousElementSibling && /^(P|H\d|UL|OL|TABLE|DIV)$/.test(box.previousElementSibling.nodeName) && !box.previousElementSibling.classList.contains('notes'))) box.insertAdjacentHTML('beforebegin', '<p><br></p>'); if (box) { box.querySelectorAll('p[data-id]').forEach(p => { if (!WB().querySelector(`.${k}ref[data-id="${p.dataset.id}"]`)) p.remove(); }); if (!box.querySelector('p')) box.remove(); else if (k === 'fn') { const en = WB().querySelector('.notes[data-k="en"]'); if (en) en.before(box); } } } }
insFootnote = () => wNote('fn');
WB().addEventListener('click', e => { const r = e.target.closest('.fnref,.enref'); if (r) { const p = WB().querySelector(`.notes p[data-id="${r.dataset.id}"]`); p && p.scrollIntoView({ block: 'center' }); } const n = e.target.closest('.notes .nnum'); if (n) { const id = n.parentElement.dataset.id; const r2 = WB().querySelector(`[data-id="${id}"].fnref,[data-id="${id}"].enref`); r2 && r2.scrollIntoView({ block: 'center' }); } });
/* Citations & bibliography */
function wSrcLabel(s, style) { const a = (s.author || 'Anon').split(/;|\band\b/)[0].trim(); const last = a.split(/[ ,]+/)[0]; return style === 'MLA' ? `(${last})` : style === 'IEEE' ? `[${(WD.sources.indexOf(s) + 1)}]` : `(${last}, ${s.year || 'n.d.'})`; }
function wSrcDlg(s) { s = s || {}; wDlg(s.tag ? 'Edit Source' : 'Create Source', `<label>Type of source</label><select id="srT">${['Book', 'Journal Article', 'Web site', 'Report', 'Conference Proceedings'].map(x => `<option ${x === s.type ? 'selected' : ''}>${x}</option>`).join('')}</select><label>Author (Last, First; separate with ;)</label><input type="text" id="srA" value="${wesc(s.author || '')}"><label>Title</label><input type="text" id="srTi" value="${wesc(s.title || '')}"><div style="display:grid;grid-template-columns:1fr 2fr;gap:6px"><div><label>Year</label><input type="text" id="srY" value="${wesc(s.year || '')}"></div><div><label>Publisher / Journal / Site</label><input type="text" id="srP" value="${wesc(s.pub || '')}"></div></div><label>City / URL / Pages</label><input type="text" id="srC" value="${wesc(s.city || '')}">`, [['OK', () => { const o = Object.assign(s, { type: wv('srT'), author: wv('srA'), title: wv('srTi'), year: wv('srY'), pub: wv('srP'), city: wv('srC') }); if (!o.tag) { o.tag = 'src' + Date.now().toString(36); WD.sources.push(o); } save(); closeG(); }]]); }
function wCiteMenu(btn) { wMenu(btn, WD.sources.map(s => ({ t: `${wesc((s.author || '').split(';')[0])}, <i>${wesc(s.title || '')}</i> (${wesc(s.year || '')})`, f: () => wHTML(`<span class="cite" contenteditable="false" data-tag="${s.tag}">${wesc(wSrcLabel(s, WD.citeStyle || 'APA'))}</span>&nbsp;`) })).concat(WD.sources.length ? ['-'] : [], [{ t: 'Add New Source…', f: () => wSrcDlg() }, { t: 'Add New Placeholder…', f: () => RB.ask('Placeholder name', 'Placeholder1', n => { if (n) wHTML(`<span class="cite" contenteditable="false">(${wesc(n)})</span>&nbsp;`); }) }])); }
function wManageSrc() { wDlg('Source Manager', `<div style="max-height:300px;overflow:auto">${WD.sources.map((s, i) => `<div style="display:flex;gap:6px;align-items:center;border-bottom:1px solid #eee;padding:4px 0"><span style="flex:1;font-size:13px">${wesc(s.author)} — <i>${wesc(s.title)}</i> (${wesc(s.year)})</span><button data-e="${i}">Edit</button><button data-d="${i}">Delete</button></div>`).join('') || '<i>No sources yet.</i>'}</div>`, [['New…', () => { closeG(); wSrcDlg(); }]]); $('gB').querySelectorAll('[data-e]').forEach(b => b.onclick = () => { closeG(); wSrcDlg(WD.sources[+b.dataset.e]); }); $('gB').querySelectorAll('[data-d]').forEach(b => b.onclick = () => { WD.sources.splice(+b.dataset.d, 1); save(); closeG(); wManageSrc(); }); }
function wCiteStyle(v) { WD.citeStyle = v; save(); wSnap(); WB().querySelectorAll('.cite[data-tag]').forEach(c => { const s = WD.sources.find(x => x.tag === c.dataset.tag); if (s) c.textContent = wSrcLabel(s, v); }); wAfter(); }
function wBiblio(kind) { if (!WD.sources.length) { alert('Add sources first (References > Insert Citation > Add New Source).'); return; } const st = WD.citeStyle || 'APA'; const L = WD.sources.slice().sort((a, b) => (a.author || '').localeCompare(b.author || '')).map((s, i) => st === 'MLA' ? `${wesc(s.author)}. <i>${wesc(s.title)}</i>. ${wesc(s.pub || '')}${s.city ? ', ' + wesc(s.city) : ''}, ${wesc(s.year)}.` : st === 'IEEE' ? `[${i + 1}] ${wesc(s.author)}, “${wesc(s.title)},” ${wesc(s.pub || '')}, ${wesc(s.year)}.` : `${wesc(s.author)} (${wesc(s.year)}). <i>${wesc(s.title)}</i>. ${wesc(s.city ? s.city + ': ' : '')}${wesc(s.pub || '')}.`); wSnap(); const old = WB().querySelector('.biblio'); const h = `<div class="biblio"><h1>${kind === 'works' ? 'Works Cited' : kind === 'refs' ? 'References' : 'Bibliography'}</h1>${L.map(x => `<p style="padding-left:.5in;text-indent:-.5in">${x}</p>`).join('')}</div>`; if (old) { old.outerHTML = h; wAfter(); } else wInsBlock(h); }
/* Captions, table of figures, index */
function wCaption(label) { const lab = label || 'Figure'; const n = WB().querySelectorAll(`.wcap[data-l="${lab}"]`).length + 1; wDlg('Caption', `<label>Caption</label><input type="text" id="cpT" value="${lab} ${n}: "><label>Label</label><select id="cpL">${['Figure', 'Table', 'Equation'].map(x => `<option ${x === lab ? 'selected' : ''}>${x}</option>`).join('')}</select><label>Position</label><select id="cpP"><option value="below">Below selected item</option><option value="above">Above selected item</option></select>`, [['OK', () => { const l = wv('cpL'); const k = WB().querySelectorAll(`.wcap[data-l="${l}"]`).length + 1; const txt = wv('cpT').replace(/^\w+\s+\d+/, l + ' ' + k); closeG(); const h = `<p class="wcap" data-l="${l}" style="font-size:9pt;color:#44546a;font-style:italic;text-align:${WPIC && WPIC.classList.contains('wcenter') ? 'center' : 'left'}">${wesc(txt)}</p>`; if (WPIC && WPIC.isConnected) { wSnap(); const b = wBlock(WPIC) || WPIC; b.insertAdjacentHTML(wv('cpP') === 'above' ? 'beforebegin' : 'afterend', h); wAfter(); } else wHTML(h); }]]); }
