function wTof() { const wHTML = wInsBlock; const L = [...WB().querySelectorAll('.wcap')]; if (!L.length) { alert('No captions found. Add captions first (References > Insert Caption).'); return; } const pageH = pg.h / 15; wHTML(`<div class="tof" contenteditable="false"><p style="font-size:14pt;color:#2f5496">Table of Figures</p>${L.map((c, i) => { if (!c.id) c.id = 'cap' + Date.now().toString(36) + i; return `<p style="display:flex;margin:2px 0"><a href="#${c.id}" class="xref" style="color:inherit;text-decoration:none">${wesc(c.textContent)}</a><span style="flex:1;border-bottom:1px dotted #777;margin:0 4px 4px"></span>${Math.floor(c.offsetTop / pageH) + 1}</p>`; }).join('')}</div>`); }
function wMarkEntry() { const r0 = wSel(); if (r0) { const q = r0.cloneRange(); q.collapse(false); lastSel = q; } const t = getSelection().toString().trim(); RB.ask('Main entry (Mark Index Entry)', t, e => { if (!e) return; wHTML(`<span class="xe" contenteditable="false" data-e="${wesc(e)}">{XE "${wesc(e)}"}</span>`); }); }
function wIndex() { const E = {}; const pageH = pg.h / 15; WB().querySelectorAll('.xe').forEach(x => { const p = Math.floor(x.offsetTop / pageH) + 1 || 1; (E[x.dataset.e] = E[x.dataset.e] || new Set()).add(p); }); const keys = Object.keys(E).sort((a, b) => a.localeCompare(b)); if (!keys.length) { alert('Mark index entries first (References > Mark Entry).'); return; } let cur = ''; const h = keys.map(k => { const L = k[0].toUpperCase(); const head = L !== cur ? (cur = L, `<p style="font-weight:700;margin-top:6px">${L}</p>`) : ''; return head + `<p style="margin:0 0 0 12px">${wesc(k)}, ${[...E[k]].join(', ')}</p>`; }).join(''); wSnap(); const old = WB().querySelector('.windex'); if (old) { old.innerHTML = h; wAfter(); } else wInsBlock(`<div class="windex" style="column-count:2">${h}</div>`); }

/* ======================= MAILINGS (mail merge) ======================= */
function wMergeRecips() { wDlg('Select Recipients', `<p style="font-size:13px">Open a CSV file (first row = field names), or type a list below (comma-separated, first line = field names).</p><button id="mrF" type="button">Use an Existing List (.csv)…</button><label>Type a New List</label><textarea id="mrT" rows="7" style="width:100%">${wesc(WD.merge ? [WD.merge.f.join(','), ...WD.merge.rows.map(r => r.join(','))].join('\n') : 'FirstName,LastName,Address,City\nJuan,Dela Cruz,123 Rizal St,Koronadal\nMaria,Santos,45 Mabini Ave,General Santos')}</textarea>`, [['OK', () => { wMergeParse(wv('mrT')); closeG(); }]]); $('mrF').onclick = () => RB.pickFile('.csv,.txt', (n, t) => { $('mrT').value = t; }, true); }
function wCsv(t) { const rows = []; let row = [], f = '', q = false; for (let i = 0; i < t.length; i++) { const ch = t[i]; if (q) { if (ch === '"') { if (t[i + 1] === '"') { f += '"'; i++; } else q = false; } else f += ch; } else if (ch === '"') q = true; else if (ch === ',') { row.push(f); f = ''; } else if (ch === '\n' || ch === '\r') { if (ch === '\r' && t[i + 1] === '\n') i++; row.push(f); rows.push(row); row = []; f = ''; } else f += ch; } if (f || row.length) { row.push(f); rows.push(row); } return rows.filter(r => r.some(x => x.trim())); }
function wMergeParse(t) { const R = wCsv(t); if (R.length < 2) { alert('Need a header row and at least one record.'); return; } WD.merge = { f: R[0].map(x => x.trim()), rows: R.slice(1), i: 0 }; save(); stMsgW(R.length - 1 + ' recipients loaded'); }
function wMergeField(btn) { if (!WD.merge) { wMergeRecips(); return; } wMenu(btn, WD.merge.f.map(f => ({ t: f, f: () => wHTML(`<span class="mfield" contenteditable="false" data-f="${wesc(f)}">«${wesc(f)}»</span>`) }))); }
function wGreeting() { if (!WD.merge) { wMergeRecips(); return; } const f = WD.merge.f; const fn = f.find(x => /first/i.test(x)) || f[0]; wHTML(`Dear <span class="mfield" contenteditable="false" data-f="${wesc(fn)}">«${wesc(fn)}»</span>,`); }
function wAddrBlock() { if (!WD.merge) { wMergeRecips(); return; } wHTML(WD.merge.f.slice(0, 4).map(f => `<span class="mfield" contenteditable="false" data-f="${wesc(f)}">«${wesc(f)}»</span>`).join('<br>')); }
function wMergePreview(on, step) { const M = WD.merge; if (!M) { alert('Select recipients first.'); return; } if (step) M.i = Math.max(0, Math.min(M.rows.length - 1, M.i + step)); const pv = on === undefined ? document.body.classList.contains('mpreview') : on; document.body.classList.toggle('mpreview', pv); wQuiet(() => WB().querySelectorAll('.mfield').forEach(e => { const k = M.f.indexOf(e.dataset.f); e.textContent = pv ? (M.rows[M.i][k] || '') : '«' + e.dataset.f + '»'; })); const b = $('wMrgN'); if (b) b.textContent = pv ? `${M.i + 1} / ${M.rows.length}` : ''; }
function wMergeFinish() { const M = WD.merge; if (!M) { alert('Select recipients first.'); return; } wMergePreview(false); const tpl = WB().innerHTML; const out = M.rows.map(r => { const d = document.createElement('div'); d.innerHTML = tpl; d.querySelectorAll('.mfield').forEach(e => e.replaceWith(document.createTextNode(r[M.f.indexOf(e.dataset.f)] || ''))); return d.innerHTML; }).join('<div class="pb" contenteditable="false">— page break —</div>'); if (!confirm(`Create a merged document with ${M.rows.length} letters? (This replaces the editor content; Undo restores it.)`)) return; wSnap(); WB().innerHTML = out; WD.merge = null; name = name + ' (merged)'; $('ttl').textContent = name + ' - Word'; wAfter(); }

/* ======================= REVIEW ======================= */
function wWordCount() { const t = (WB().innerText || '').replace(/​/g, ''); const words = t.trim() ? t.trim().split(/\s+/).length : 0; const paras = [...WB().querySelectorAll('p,h1,h2,h3,h4,li')].filter(p => p.textContent.trim()).length; const pages = (($('stL').textContent.match(/of (\d+)/) || [0, 1])[1]); const sel = getSelection().toString(); wDlg('Word Count', `<table style="width:100%;font-size:14px">${[['Pages', pages], ['Words', words], ['Characters (no spaces)', t.replace(/\s/g, '').length], ['Characters (with spaces)', t.replace(/\n/g, '').length], ['Paragraphs', paras], ['Lines (approx.)', Math.ceil(t.replace(/\n/g, '').length / 90) || 0]].map(r => `<tr><td>${r[0]}</td><td style="text-align:right"><b>${r[1]}</b></td></tr>`).join('')}${sel ? `<tr><td colspan=2 style="color:#555;padding-top:6px">Selection: ${sel.trim() ? sel.trim().split(/\s+/).length : 0} words</td></tr>` : ''}</table><label><input type="checkbox" checked disabled> Include textboxes, footnotes and endnotes</label>`, []); }
wc = wWordCount;
let WSPK = null;
function wReadAloud() { if (!('speechSynthesis' in window)) { alert('Read Aloud is not available on this device.'); return; } if (speechSynthesis.speaking) { speechSynthesis.cancel(); WSPK = null; stMsgW('Read Aloud stopped'); return; } const s = getSelection().toString(); const t = s || WB().innerText; const u = new SpeechSynthesisUtterance(t.slice(0, 32000)); u.rate = WD.rate || 1; WSPK = u; speechSynthesis.speak(u); stMsgW('Reading aloud… press again to stop'); }
function wProtect() { if (WD.locked) { RB.ask('Password to stop protection', '', p => { if ((p || '') === (WD.lockPw || '')) { WD.locked = false; save(); wLockPaint(); } else alert('Wrong password.'); }); return; } RB.ask('Restrict Editing — password (optional)', '', p => { if (p === null) return; WD.locked = true; WD.lockPw = p || ''; save(); wLockPaint(); }); }
function wLockPaint() { [WB(), $('hdr'), $('ftr')].forEach(e => e.contentEditable = WD.locked ? 'false' : 'true'); const b = $('wLockBtn'); if (b) b.classList.toggle('act', !!WD.locked); if (WD.locked) stMsgW('Document is protected (read-only)'); }
function wAuthor() { RB.ask('User name (for comments and tracked changes)', WD.author, n => { if (!n) return; WD.author = n; try { localStorage.setItem('hub_author', n); } catch (e) { } save(); }); }
function wCompare() { RB.pickFile('.docx,.txt,.html', async (n, buf) => { let html = ''; if (/\.docx$/i.test(n)) html = (await mammoth.convertToHtml({ arrayBuffer: buf })).value; else html = new TextDecoder().decode(buf); const d = document.createElement('div'); d.innerHTML = html; const A = (d.innerText || '').split(/\s+/), B = (WB().innerText || '').split(/\s+/); const N = A.length, M = B.length; if (N * M > 4e6) { alert('Documents are too large to compare here.'); return; } const L = Array.from({ length: N + 1 }, () => new Uint16Array(M + 1)); for (let i = N - 1; i >= 0; i--) for (let j = M - 1; j >= 0; j--) L[i][j] = A[i] === B[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1]); let i = 0, j = 0, out = ''; while (i < N || j < M) { if (i < N && j < M && A[i] === B[j]) { out += wesc(A[i]) + ' '; i++; j++; } else if (j < M && (i >= N || L[i][j + 1] >= L[i + 1][j])) { out += `<ins class="trk" data-a="Compare">${wesc(B[j])}</ins> `; j++; } else { out += `<del class="trk" data-a="Compare">${wesc(A[i])}</del> `; i++; } } wSnap(); const keep = WB().innerHTML; if (!confirm('Show the comparison (original vs current) in the editor? Undo restores your document.')) return; WB().innerHTML = `<p><b>Compared document:</b> original “${wesc(n)}” → current. Insertions underlined, deletions struck through.</p><p>${out}</p>`; wAfter(); }); }

/* ======================= VIEW ======================= */
function wView(m) { ['read', 'web', 'outline', 'draft'].forEach(c => document.body.classList.remove(c)); if (m === 'read') { document.body.classList.add('read'); MODE = 'reflow'; } else if (m === 'web') { document.body.classList.add('web'); } else if (m === 'outline') document.body.classList.add('outline'); else if (m === 'draft') document.body.classList.add('draft'); if (m === 'print') MODE = 'auto'; fit(); document.querySelectorAll('#status .vw b').forEach(b => b.classList.toggle('on', b.dataset.v === m)); }
function wZoomDlg() { wDlg('Zoom', `<div style="display:grid;grid-template-columns:1fr 1fr;gap:4px">${[200, 100, 75, 50].map(z => `<label><input type="radio" name="zz" value="${z}" ${Math.round(uz * 100) === z ? 'checked' : ''}> ${z}%</label>`).join('')}<label><input type="radio" name="zz" value="pw"> Page width</label><label><input type="radio" name="zz" value="wp"> Whole page</label></div><label>Percent</label><input type="number" id="zzP" value="${Math.round(uz * 100)}">`, [['OK', () => { const r = document.querySelector('input[name=zz]:checked'); const v = r ? r.value : ''; closeG(); if (v === 'pw') pageWidth(); else if (v === 'wp') { setZ(($('desk').clientHeight - 20) / (pg.h / 15)); } else setZ((+(v || wv('zzP')) || 100) / 100); }]]); }
function wRuler() { const R = $('wruler'); if (!R || !document.body.classList.contains('ruler')) return; const P = WP().getBoundingClientRect(), D = $('desk').getBoundingClientRect(); const w = P.width, x0 = P.left - D.left; const m = WD.marg || [1, 1, 1, 1]; const ppi = w / (pg.w / 1440); let h = `<div class="mg" style="left:${x0}px;width:${m[1] * ppi}px"></div><div class="mg" style="left:${x0 + w - m[3] * ppi}px;width:${m[3] * ppi}px"></div>`; for (let i = 0; i <= pg.w / 1440 * 8; i++) { const x = x0 + i * ppi / 8; h += `<div class="tk" style="left:${x}px;height:${i % 8 === 0 ? 10 : i % 4 === 0 ? 6 : 3}px"></div>` + (i % 8 === 0 && i ? `<span style="position:absolute;left:${x - 3}px;top:0;font-size:9px;color:#666">${i / 8}</span>` : ''); } R.innerHTML = h; }
$('desk').addEventListener('scroll', () => { }, { passive: true }); window.addEventListener('resize', wRuler);
function wToggleBody(c) { document.body.classList.toggle(c); if (c === 'ruler') wRuler(); const b = document.querySelector(`[data-tog="${c}"]`); if (b) b.classList.toggle('act', document.body.classList.contains(c)); }
function wFocus() { if (!document.fullscreenElement) { (document.documentElement.requestFullscreen || (() => { }))?.call(document.documentElement); document.body.classList.add('read'); } else { document.exitFullscreen && document.exitFullscreen(); document.body.classList.remove('read'); } }

