function wPrint() { wDlg('Print', `<label>Copies</label><input type="number" id="prC" value="1" min="1"><label>Pages</label><select id="prP"><option>Print All Pages</option></select><label>Paper</label><input type="text" disabled value="${(WSIZES[pgS.sz] || ['Letter'])[0]}, ${pgS.land ? 'Landscape' : 'Portrait'}"><p style="font-size:12px;color:#555">Uses your device's print service. Choose "Save as PDF" there to make a PDF.</p>`, [['Print', () => { closeG(); wPrintNow(); }]]); }
