function wSaveMd() { const md = [...WB().children].map(e => { const t = e.innerText || ''; if (/^H[1-6]$/.test(e.nodeName)) return '#'.repeat(+e.nodeName[1]) + ' ' + t; if (e.nodeName === 'UL') return [...e.children].map(li => '- ' + li.innerText).join('\n'); if (e.nodeName === 'OL') return [...e.children].map((li, i) => (i + 1) + '. ' + li.innerText).join('\n'); if (e.nodeName === 'TABLE') { const R = [...e.rows].map(r => '| ' + [...r.cells].map(c => c.innerText.replace(/\|/g, '\\|')).join(' | ') + ' |'); if (R.length) R.splice(1, 0, '|' + ' --- |'.repeat(e.rows[0].cells.length)); return R.join('\n'); } return t; }).join('\n\n'); RB.saveBlob(name + '.md', new Blob([md], { type: 'text/markdown' }), 'text/markdown'); }
fileMenu = function () { const it = (ic, t, f, k) => `<div class="wfm" style="display:flex;padding:11px 6px;border-bottom:1px solid #eee;font-size:15px;cursor:pointer" onclick="closeG();${f}"><span style="width:30px">${ic}</span><span style="flex:1">${t}</span><small style="color:#888">${k || ''}</small></div>`;
  wDlg('File', it('&#128196;', 'New (templates)…', 'wNewMenu()', 'Ctrl+N') + it('&#128194;', 'Open…', 'openDoc()', 'Ctrl+O') + it('&#128190;', 'Save as Word (.docx)', 'saveDocx()', 'Ctrl+S') + it('&#127760;', 'Save as Web Page (.html)', 'saveHtml()') + it('&#128221;', 'Save as Plain Text (.txt)', 'wSaveTxt()') + it('&#11015;', 'Save as Markdown (.md)', 'wSaveMd()') + it('&#128424;', 'Print / Save as PDF…', 'wPrint()', 'Ctrl+P') + it('&#128444;', 'Convert to image / PDF…', 'exportPdfConv()') + it('&#9432;', 'Properties…', 'wProps()') + it('&#128100;', 'Options — user name…', 'wAuthor()') + it('&#128274;', (WD.locked ? 'Stop protection' : 'Protect Document (read-only)…'), 'wProtect()'), []); };

/* ======================= small extras: chart, dictate, header/footer gallery, page numbers ======================= */
function wChartDlg(img) { const D = img && img.dataset.chart ? JSON.parse(img.dataset.chart) : { t: 'col', title: 'Chart Title', csv: 'Category,Series 1,Series 2\nItem 1,4.3,2.4\nItem 2,2.5,4.4\nItem 3,3.5,1.8\nItem 4,4.5,2.8' };
  wDlg('Insert Chart', `<label>Chart type</label><select id="chT">${[['col', 'Clustered Column'], ['bar', 'Bar'], ['line', 'Line'], ['pie', 'Pie'], ['area', 'Area']].map(x => `<option value="${x[0]}" ${x[0] === D.t ? 'selected' : ''}>${x[1]}</option>`).join('')}</select><label>Title</label><input type="text" id="chTi" value="${wesc(D.title)}"><label>Data (first row = series names, first column = categories)</label><textarea id="chD" rows="6" style="width:100%;font-family:monospace">${wesc(D.csv)}</textarea><canvas id="chC" width="640" height="380" style="width:100%;border:1px solid #ddd;margin-top:6px"></canvas>`, [['OK', () => { const d = { t: wv('chT'), title: wv('chTi'), csv: wv('chD') }; const url = $('chC').toDataURL('image/png'); closeG(); if (img) { wSnap(); img.src = url; img.dataset.chart = JSON.stringify(d); wAfter(); } else wHTML(`<img src="${url}" data-chart='${wesc(JSON.stringify(d))}' style="width:480px">`); }]], true);
  const draw = () => { const cv = $('chC'); if (!cv) return; const g = cv.getContext('2d'), W = cv.width, H = cv.height; g.fillStyle = '#fff'; g.fillRect(0, 0, W, H); const R = wCsv(wv('chD')); if (R.length < 2) return; const names = R[0].slice(1), cats = R.slice(1).map(r => r[0]), vals = names.map((_, j) => R.slice(1).map(r => +r[j + 1] || 0)); const pal = ['#4472C4', '#ED7D31', '#A5A5A5', '#FFC000', '#5B9BD5', '#70AD47']; const t = wv('chT'); g.font = 'bold 20px Calibri,sans-serif'; g.fillStyle = '#333'; g.textAlign = 'center'; g.fillText(wv('chTi'), W / 2, 28); g.font = '14px Calibri,sans-serif';
    if (t === 'pie') { const v = vals[0], tot = v.reduce((a, b) => a + b, 0) || 1; let a0 = -Math.PI / 2; const cx = W / 2 - 60, cy = H / 2 + 14, r = 140; v.forEach((x, i) => { const a1 = a0 + x / tot * Math.PI * 2; g.beginPath(); g.moveTo(cx, cy); g.arc(cx, cy, r, a0, a1); g.fillStyle = pal[i % 6]; g.fill(); a0 = a1; g.fillRect(W - 150, 70 + i * 24, 14, 14); g.fillStyle = '#333'; g.textAlign = 'left'; g.fillText(cats[i], W - 130, 82 + i * 24); }); return; }
    let mx = 0; vals.forEach(a => a.forEach(v => mx = Math.max(mx, v))); mx = mx * 1.1 || 1; const x0 = 50, y0 = H - 40, pw = W - 170, ph = H - 90, n = cats.length; g.strokeStyle = '#ddd'; for (let i = 0; i <= 5; i++) { const y = y0 - ph * i / 5; g.beginPath(); g.moveTo(x0, y); g.lineTo(x0 + pw, y); g.stroke(); g.fillStyle = '#666'; g.textAlign = 'right'; g.fillText(+(mx * i / 5).toFixed(1), x0 - 6, y + 4); }
    cats.forEach((c, i) => { g.fillStyle = '#444'; g.textAlign = 'center'; g.fillText(String(c).slice(0, 12), x0 + (i + .5) * pw / n, y0 + 18); }); const bw = pw / n * .7 / names.length;
    vals.forEach((a, j) => { g.fillStyle = g.strokeStyle = pal[j % 6]; if (t === 'col') a.forEach((v, i) => g.fillRect(x0 + i * pw / n + pw / n * .15 + j * bw, y0 - v / mx * ph, bw, v / mx * ph)); else if (t === 'bar') a.forEach((v, i) => { const bh = ph / n * .7 / names.length; g.fillRect(x0, y0 - ph + i * ph / n + ph / n * .15 + j * bh, v / mx * pw, bh); }); else { g.lineWidth = 3; g.beginPath(); a.forEach((v, i) => { const x = x0 + (i + .5) * pw / n, y = y0 - v / mx * ph; i ? g.lineTo(x, y) : g.moveTo(x, y); }); if (t === 'area') { g.lineTo(x0 + (n - .5) * pw / n, y0); g.lineTo(x0 + .5 * pw / n, y0); g.globalAlpha = .6; g.fill(); g.globalAlpha = 1; } else g.stroke(); } g.fillRect(W - 110, 70 + j * 24, 14, 14); g.fillStyle = '#333'; g.textAlign = 'left'; g.fillText(names[j], W - 90, 82 + j * 24); }); };
  $('gB').querySelectorAll('input,select,textarea').forEach(e => e.addEventListener('input', draw)); draw(); }
