function wDictate() { const SR = window.SpeechRecognition || window.webkitSpeechRecognition; if (!SR) { alert('Dictation is not available in this WebView. Use your keyboard\'s microphone button instead.'); return; } if (WREC) { WREC.stop(); WREC = null; $('wDicBtn') && $('wDicBtn').classList.remove('act'); return; } WREC = new SR(); WREC.continuous = true; WREC.interimResults = false; WREC.lang = navigator.language || 'en-US'; WREC.onresult = e => { for (let i = e.resultIndex; i < e.results.length; i++) if (e.results[i].isFinal) wHTML(wesc(e.results[i][0].transcript) + ' '); }; WREC.onend = () => { WREC = null; $('wDicBtn') && $('wDicBtn').classList.remove('act'); }; WREC.start(); $('wDicBtn') && $('wDicBtn').classList.add('act'); }
