function wQuickField(btn) { wMenu(btn, [{ t: 'Author', f: () => wHTML(wesc(WD.author)) }, { t: 'File Name', f: () => wHTML(wesc(name)) }, { t: 'Date (updates)', f: () => wHTML(`<span class="fld" contenteditable="false" data-f="DATE">${new Date().toLocaleDateString()}</span>`) }, { t: 'Page Number', f: () => wHTML('<span class="fld" contenteditable="false" data-f="PAGE">#</span>') }, { t: 'Number of Pages', f: () => wHTML('<span class="fld" contenteditable="false" data-f="NUMPAGES">N</span>') }, { t: 'Horizontal Line', f: () => wHTML('<hr>') }, { t: 'Signature Line…', f: () => RB.ask('Suggested signer', WD.author, n => { if (n) wHTML(`<div style="width:260px;margin-top:30px"><div style="border-bottom:1px solid #000;height:40px">✕</div><div>${wesc(n)}</div></div><p><br></p>`); }) }]); }
