function wBordersMenu(btn) { const inT = !!cellOf(); const k = (t, ic, kind) => ({ ic, t, f: () => inT ? wCellBorders(kind) : wParaBorder(kind) }); wMenu(btn, [k('Bottom Border', '▁', 'bottom'), k('Top Border', '▔', 'top'), k('Left Border', '▏', 'left'), k('Right Border', '▕', 'right'), k('No Border', '□', 'none'), k('All Borders', '⊞', 'all'), k('Outside Borders', '▢', 'out'), '-', { ic: '―', t: 'Horizontal Line', f: () => wHTML('<hr>') }, { t: 'Borders and Shading…', f: wBordDlg }]); }
